package com.toolbox.tools.integration;
import java.util.*;
public final class SyncEngine{public static final int MAX_HISTORY=32;private final Map<String,NormalizedRecord> local=new LinkedHashMap<>();private final Deque<String> history=new ArrayDeque<>();private String cursor="none";private long revision=-1;private boolean localDirty;
public synchronized void markLocalDirty(){localDirty=true;}
public synchronized SyncPlan plan(ExternalSnapshot remote,NormalizationResult normalized){if(!normalized.isPass())throw new IllegalArgumentException("normalization failed");if(remote.cursor().equals(cursor)&&remote.revision()==revision)return new SyncPlan(SyncStatus.NO_CHANGE,remote.cursor(),remote.revision(),Collections.emptyList());if(localDirty&&revision>=0&&remote.revision()!=revision)return new SyncPlan(SyncStatus.CONFLICT,remote.cursor(),remote.revision(),normalized.records());return new SyncPlan(SyncStatus.CLEAN,remote.cursor(),remote.revision(),normalized.records());}
public synchronized void apply(SyncPlan p){if(p.status()==SyncStatus.CONFLICT)throw new IllegalStateException("SYNC_CONFLICT");if(p.status()==SyncStatus.NO_CHANGE)return;local.clear();for(NormalizedRecord r:p.records())local.put(r.stableId(),r);cursor=p.cursor();revision=p.revision();localDirty=false;history.addLast(cursor+"#"+revision);while(history.size()>MAX_HISTORY)history.removeFirst();}
public synchronized List<NormalizedRecord> local(){return Collections.unmodifiableList(new ArrayList<>(local.values()));}public synchronized String cursor(){return cursor;}public synchronized int historySize(){return history.size();}}
